<div class="p-6 space-y-4"><h1 class="text-2xl font-bold">{{ $exam->name }} — Exam Paper</h1>@if($message)<p class="text-green-700">{{ $message }}</p>@endif@if(!$schedule)<p>No schedule available.</p>@else<form wire:submit="add" class="flex gap-2"><select wire:model="form.question_version_id" class="border p-2"><option value="">Question version</option>@foreach($versions as $v)<option value="{{ $v->id }}">{{ $v->question->stable_key }} v{{ $v->version }}</option>@endforeach</select><input wire:model="form.ordinal" placeholder="Question no." class="border p-2"><input wire:model="form.marks" placeholder="Marks" class="border p-2"><button class="bg-blue-600 text-white p-2">Add</button></form>@if($paper)<p>Total marks: {{ $paper->total_marks }}</p><ol>@foreach($paper->questions as $q)<li>{{ $q->ordinal }}. {{ $q->version->prompt }} ({{ $q->marks }}) <button wire:click="remove({{ $q->id }})" class="text-red-600">Remove</button> <button wire:click="reorder({{ $q->id }}, {{ $q->ordinal + 1 }})" class="text-blue-600">Move down</button></li>@endforeach</ol>@else<p>Paper তৈরি হয়নি। প্রথম প্রশ্ন যোগ করলে paper তৈরি হবে।</p>@endif@endif</div>
